ev("xm25b","2025-06-28","샤오미코리아",PM,"샤오미 스토어 IFC몰 여의도점 오픈 이벤트(6월 28~29일)로 5만 원 이상 구매 400명, 10만 원 이상 200명에게 선착순 선물을 주고 스마트밴드 10 구매 50명에게 한정 선물을, 현장 미션 완료자에게 럭키드로우를 했다.",["xm_ins2506"],channel="샤오미 스토어 IFC몰 여의도점",benefit="선착순 선물, 한정 선물, 럭키드로우",period_start="2025-06-28",period_end="2025-06-29",flags=["선물 품목은 기사에 없음"],imp=3)
ev("xm25c","2025-09-18","샤오미코리아",PM,"샤오미가 추석 빅세일(10월 12일까지, mi.com과 Mi Store 앱)을 열었다. 레드미 태블릿 등 구매 시 사은품, 일부 레드미·POCO 폰 최대 20% 할인, TV 최대 10% 할인, 20만 원 이상 구매 시 1만 원 쿠폰을 줬다. 2호점·3호점 개점(9월 27일)도 알렸다.",["xm_ins2509"],channel="mi.com, Mi Store 앱",benefit="사은품, 최대 20% 폰 할인, TV 최대 10% 할인, 쿠폰",period_end="2025-10-12",rec="정기",flags=["쿠폰 중복 적용은 불가","개시일은 기사 게재일 기준"],imp=3)
ev("xm25d","2025-09-25","샤오미코리아",PR,"샤오미가 9월 25일 19시 네이버 쇼핑라이브에서 신제품을 소개하고 20시 판매를 시작했다. 15T 프로 구매자에게 10월 19일까지 보조배터리와 레드미 버즈 6 프로를 주고, 매장 오픈 예약 시 약 6만 원 상당 포인트, 신제품 사전 예약 시 약 1만 7천 원 상당 포인트를 줬다. 오프라인 일부 카드 20만 원 이상 12개월 무이자다.",["xm_ins2509b"],channel="네이버 쇼핑라이브, 공식 판매처",product="샤오미 15T Pro 외",benefit="사은품, 포인트, 무이자 할부",period_end="2025-10-19",imp=3,flags=["포인트 금액은 '약' 표기"])
ev("xm25e","2025-11-22","샤오미코리아",PM,"샤오미코리아가 2025 블랙프라이데이(11월 30일까지)에서 주요 제품을 최대 29% 할인했다. 샤오미 15 울트라(16GB+512GB)는 169만 9천 원에서 149만 9천 원, 샤오미 15(12GB+256GB)는 110만 9,900원에서 95만 9,900원이다. 공식 웹사이트에서 미션 시 최대 1,500포인트와 5% 쿠폰, 신규 회원 8% 쿠폰을 줬다.",["xm_hk2511"],channel="샤오미 공식 채널",benefit="최대 29% 할인, 포인트, 쿠폰",period_end="2025-11-30",rec="정기",imp=3,flags=["스마트폰 중심이며 가전 할인 내용은 기사에 없음"])
ev("xm26","2026-04-07","샤오미코리아",PM,"샤오미가 샤오미 팬 페스티벌 2026(4월 20일까지)을 열어 공식 온라인 스토어 중심으로 최대 43% 할인했다. 포인트 결제 추가 할인율을 5%에서 최대 10%로 올리고 30만·50만·100만 원 이상 구매 시 3만·5만·10만 원 상품권을 선착순으로 줬다. 로봇청소기, 무선청소기, TV 등을 미닷컴, 샤오미 오프라인 스토어, 쿠팡, 네이버, SSG닷컴에서 순차 특가했고 네이버 브랜드스토어 오픈 이벤트도 열었다.",["xm_fn2604"],channel="미닷컴, 오프라인 스토어, 쿠팡, 네이버, SSG닷컴",benefit="최대 43% 할인, 상품권, 포인트",period_end="2026-04-20",rec="정기",imp=3,flags=["16주년·50여 개국 행사라는 서술로 연례 행사로 보이나 이전 한국 개최 기록은 확인하지 못함"])
